class JEPABlock(nn.Module):
    def __init__(
        self,
        dim,
        num_heads,
        mlp_ratio=4.0,
        qkv_bias=False,
        qk_scale=None,
        drop=0.,
        attn_drop=0.,
        act_layer=nn.GELU,
        norm_layer=nn.LayerNorm,
        rotary_pes=False
    ):
        super().__init__()
        self.norm1 = norm_layer(dim)
        self.attn = MultiHeadAttention(
            dim,
            num_heads=num_heads,
            qkv_bias=qkv_bias,
            qk_scale=qk_scale,
            attn_drop=attn_drop,
            proj_drop=drop,
            rotary_pes=rotary_pes
            )

        self.norm2 = norm_layer(dim)
        self.rotary_pes = rotary_pes 
        mlp_hidden_dim = int(dim * mlp_ratio)
        self.mlp = MLP(
            in_features=dim,
            hidden_features=mlp_hidden_dim,
            act_layer=act_layer,
            drop=drop)

    def forward(self, x, mask=None):
        x = self.norm1(x)
        y = self.attn(x, key=x, value=x, mask=mask)
        if x.is_nested:
            # idk why this is needed, for some reason x+y doesn't work
            x = coerce_offsets(x, y)
        x = x + y
        x = x + self.mlp(self.norm2(x))
        return x

def apply_masks(x, masks):
    all_x = []
    for m, x_i in zip(masks, x):
        # if 0 in m and not masks.is_nested:
        # # need to remove 0 indices due to possible padding
        #     rev_m = reversed(m)
        #     max_idx = torch.argmax((rev_m > 0).to(int))
        #     if torch.all(rev_m[0:max_idx]==0):
        #         m = m[:-max_idx]
        mask_keep = m.unsqueeze(-1).repeat(1, x_i.size(-1))
        x_i_masked = torch.gather(x_i, dim=0, index=mask_keep)
        assert x_i_masked.shape[0] == mask_keep.shape[0], "The number of masked tokens does not match the number of masked positions"
        all_x.append(x_i_masked)
    if masks.is_nested:
        return torch.nested.as_nested_tensor(all_x, layout=torch.jagged)
    else:
        return torch.stack(all_x, dim=0)


def create_masks(x, patch_size, patch_stride, context_mask_range, target_mask_range, melt_channels_to_batch=False, return_nested=False):
    # Create the mask for the patches

    batch_size = 0
    sample_n_patches = []
    for x_i in x:
        if x_i.dim() == 2:
           # print(x_i.shape)
            channel_size = x_i.size(0)
            seq_len = x_i.size(-1)

            if (seq_len - patch_size) % patch_stride != 0:
                pad_amount = patch_stride - ((seq_len - patch_size) % patch_stride)
                seq_len = seq_len + pad_amount

            # Correct formula for number of patches
            num_patches = int((seq_len - patch_size) // patch_stride + 1)
        elif x_i.dim() == 3:
            # the data is already patched pf size: num_patches x nvars x len
            channel_size = x_i.size(1)
            num_patches = x_i.size(0)
        else:
            raise ValueError("Input tensor x_i must be 2D or 3D")


        #if ((x_i.size(-1)-patch_size) % patch_stride != 0):
        #    num_patches += 1
        if melt_channels_to_batch:
            added_batches = channel_size
            batch_size += added_batches
            sample_n_patches.extend(num_patches for i in range(added_batches))
        else:
            batch_size += 1
            sample_n_patches.append(num_patches)
    
    target_indices_t = []
    context_indices_t = []

    for i, n_patch in enumerate(sample_n_patches):
        target_ratio = target_mask_range[0] + torch.rand(1).item() * (target_mask_range[1] - target_mask_range[0])
        context_ratio = context_mask_range[0] + torch.rand(1).item() * (context_mask_range[1] - context_mask_range[0])
        perm = torch.randperm(n_patch)
        num_target = int(n_patch * target_ratio)
        remaining = n_patch - num_target
        num_context = int(remaining * context_ratio)
                    
        target_indices = perm[:num_target]
        context_indices = perm[num_target:num_target + num_context]

        assert len(target_indices) > 0, f"No target indices created, x: {[x_i.shape for x_i in x]} n_patch: {n_patch}, target_ratio: {target_ratio}, num_target: {num_target}, perm: {perm}, patch_size: {patch_size}, patch_stride: {patch_stride}, num_patches: {sample_n_patches}"
        assert len(context_indices) > 0, "No context indices created"
        assert set(target_indices).isdisjoint(context_indices), "Target and context indices overlap"

        target_indices_t.append(target_indices.sort().values)
        context_indices_t.append(context_indices.sort().values)
    if return_nested:
        mask_indices = torch.nested.as_nested_tensor(target_indices_t, layout=torch.jagged)
        non_mask_indices = torch.nested.as_nested_tensor(context_indices_t, layout=torch.jagged)
    else:
        #mask_indices = torch.stack(target_masks, dim=0)
        #non_mask_indices = torch.stack(context_masks, dim=0)
        min_target_len = min(len(mask) for mask in target_indices_t) # make them all the same
        min_context_len = min(len(mask) for mask in context_indices_t)

        mask_indices = torch.zeros((batch_size, min_target_len), dtype=torch.long)
        non_mask_indices = torch.zeros((batch_size, min_context_len), dtype=torch.long)

        for i in range(batch_size):
            mask_indices[i, :] = target_indices_t[i][:min_target_len]
            non_mask_indices[i, :] = context_indices_t[i][:min_context_len]
    return mask_indices, non_mask_indices

def create_masks_around_targets(bs, num_patches, max_context_distance=10, target_mask_range=(0.05, 0.25), context_mask_range=(0.5, 1.)):
    """
    Creates different masks for each batch item, with consistent sizes.
    
    Args:
        bs: Batch size
        num_patches: Number of patches in sequence
        max_context_distance: Maximum distance between a target and its context patches
        target_ratio_range: Range for ratio of patches to use as targets
        context_ratio_range: Range for ratio of context to select from available context
        
    Returns:
        mask_indices: Target patch indices [bs, num_targets]
        non_mask_indices: Context patch indices [bs, num_context]
    """
    # Define random variables upfront (same for all batch items)
    target_ratio = target_mask_range[0] + torch.rand(1).item() * (target_mask_range[1] - target_mask_range[0])
    num_targets = max(1, int(num_patches * target_ratio))
    
    context_ratio = context_mask_range[0] + torch.rand(1).item() * (context_mask_range[1] - context_mask_range[0])
    
    # Initialize result containers
    mask_indices_batch = []
    non_mask_indices_batch = []
    min_context_size = 1000
    
    # Create masks for each batch item
    for _ in range(bs):
        # 1. Randomly select target patches for this batch item
        perm = torch.randperm(num_patches)
        target_indices = perm[:num_targets]
        
        # 2. Create context windows around targets
        context_mask = torch.zeros(num_patches, dtype=torch.bool)
        
        for idx in target_indices:
            # Add context around this target
            start = max(0, idx - max_context_distance)
            end = min(num_patches, idx + max_context_distance + 1)
            context_mask[start:end] = True
        
        # Remove targets from context
        for idx in target_indices:
            context_mask[idx] = False
        
        # Get all potential context indices
        potential_context_indices = torch.nonzero(context_mask).squeeze(-1)
        
        # 3. Randomly select a subset of context patches
        num_context = max(1, int(len(potential_context_indices) * context_ratio))
        num_context = min(num_context, len(potential_context_indices))
        
        if len(potential_context_indices) > 0:
            perm_context = torch.randperm(len(potential_context_indices))
            context_indices = potential_context_indices[perm_context[:num_context]]
        else:
            # Fallback if no context available
            context_indices = torch.tensor([], dtype=torch.long)
        
        # Track the maximum context size we've seen
        min_context_size = min(min_context_size, len(context_indices))
        
        # Add to our batch lists
        mask_indices_batch.append(target_indices)
        non_mask_indices_batch.append(context_indices)
    
    # Create uniformly sized tensors
    mask_indices = torch.zeros((bs, num_targets), dtype=torch.long)
    non_mask_indices = torch.zeros((bs, min_context_size), dtype=torch.long)
    # Fill tensors with actual indices
    for i in range(bs):
        mask_indices[i, :] = mask_indices_batch[i]
        
        context_len = len(non_mask_indices_batch[i])
        if context_len > 0:
            non_mask_indices[i, :min_context_size] = non_mask_indices_batch[i][:min_context_size]
    
    return mask_indices, non_mask_indices

def generate_block_masks(x, patch_size, patch_stride, context_ratio_range, target_ratio_range, min_block_size, max_block_size, melt_channels_to_batch=False, return_nested=True):
    """
    Generates block masks for time series data.

    Args:
        x: tensor of time series data.
        patch_size: Size of each patch.
        patch_stride: Stride of the patches.
        context_ratio_range: Tuple indicating the min and max ratio of context patches.
        target_ratio_range: Tuple indicating the min and max ratio of target patches.
        min_block_size: Minimum size of a block.
        max_block_size: Maximum size of a block (defaults to 25% of num_patches).
        return_nested: Whether to return nested tensors or 0 padded tensors.
    Returns:
        masks (target_masks): Tensor of target indices for each sequence in the batch.
        non_masks (context_masks): Tensor of context indices for each sequence in the batch.
    """

    if not return_nested and (context_ratio_range[0] != context_ratio_range[1] or target_ratio_range[0] != target_ratio_range[1] or min_block_size != max_block_size):
        warnings.warn("When not returning nested tensors, the context and target ratio ranges must be the same, as well as the min and max block size. Setting context and target ratio ranges to the max value and min block size to max block size.")
        context_ratio_range = (context_ratio_range[1], context_ratio_range[1])
        target_ratio_range = (target_ratio_range[1], target_ratio_range[1])
        min_block_size = max_block_size

    target_masks = []
    context_masks = []

    sample_n_patches = []
    batch_size = 0
    channel_size = x.size(1)
    for x_i in x:
        num_patches = int((max(x_i.size(-1), patch_size)-patch_stride) // patch_stride + 1)
        if ((x_i.size(-1)-patch_size) % patch_stride != 0):
            num_patches += 1
        if melt_channels_to_batch:
            added_batches = channel_size
            batch_size += added_batches
            sample_n_patches.extend(num_patches for i in range(added_batches))
        else:
            batch_size += 1
            sample_n_patches.append(num_patches)

    assert max_block_size >= min_block_size, "Max block size must be >= min block size"
    for num_patches in sample_n_patches:
        assert max_block_size < num_patches, "Max block size must be less than the number of patches"
        
        mask = torch.ones(num_patches, dtype=torch.bool)
        target_ratio = target_ratio_range[0] + torch.rand(1).item() * (target_ratio_range[1] - target_ratio_range[0])
        context_ratio = context_ratio_range[0] + torch.rand(1).item() * (context_ratio_range[1] - context_ratio_range[0])

        # Determine target size
        target_size = min(math.ceil(num_patches * target_ratio), num_patches - 1)
        # Generate target blocks
        target_indices = []
        while len(target_indices) < target_size:
            remaining_size = target_size - len(target_indices)
            block_size = min(
                torch.randint(min_block_size, max_block_size + 1, size=(1,)).item(),
                remaining_size
            )
            valid_starts = torch.nonzero(mask[:-block_size]).squeeze(-1)
            if len(valid_starts) == 0:
                break
            start_idx = valid_starts[torch.randint(0, len(valid_starts), (1,))]
            block_indices = torch.arange(start_idx.item(), start_idx.item() + block_size)
            mask[block_indices] = 0
            target_indices.extend(block_indices.tolist())

        # Remaining indices for context
        remaining_mask = torch.ones(num_patches, dtype=torch.bool)
        remaining_mask[target_indices] = 0
        num_remaining = torch.sum(remaining_mask).item()
        context_size = min(math.ceil(num_remaining * context_ratio), num_remaining)
        context_indices = []

        # Generate context blocks
        while len(context_indices) < context_size:
            remaining_size = context_size - len(context_indices)
            block_size = min(torch.randint(min_block_size, max_block_size+1, size=(1,)).item(), remaining_size)
            valid_starts = torch.nonzero(remaining_mask[:-block_size]).squeeze(-1)
            if len(valid_starts) == 0:
                break
            start_idx = valid_starts[torch.randint(0, len(valid_starts), (1,))]
            block_indices = torch.arange(start_idx.item(), start_idx.item() + block_size)
            # Only add block if it doesn't overlap with target indices
            if remaining_mask[block_indices].all():
                remaining_mask[block_indices] = 0
                context_indices.extend(block_indices.tolist())
        assert len(target_indices) > 0, "No target indices created"
        assert len(context_indices) > 0, "No context indices created"
        assert set(target_indices).isdisjoint(context_indices), "Target and context indices overlap"
        # Convert to sorted tensors
        target_indices = torch.tensor(target_indices, dtype=torch.long)
        context_indices = torch.tensor(context_indices, dtype=torch.long)
        #target_indices = target_indices[torch.randperm(len(target_indices))]
        #context_indices = context_indices[torch.randperm(len(context_indices))]
        target_masks.append(target_indices)
        context_masks.append(context_indices)

    # Pad masks to uniform size
    if return_nested:
        mask_indices = torch.nested.as_nested_tensor(target_masks, layout=torch.jagged)
        non_mask_indices = torch.nested.as_nested_tensor(context_masks, layout=torch.jagged)
    else:
        #mask_indices = torch.stack(target_masks, dim=0)
        #non_mask_indices = torch.stack(context_masks, dim=0)
        min_target_len = min(len(mask) for mask in target_masks) # make them all the same
        min_context_len = min(len(mask) for mask in context_masks)

        mask_indices = torch.zeros((batch_size, min_target_len), dtype=torch.long)
        non_mask_indices = torch.zeros((batch_size, min_context_len), dtype=torch.long)

        for i in range(batch_size):
            mask_indices[i, :] = target_masks[i][:min_target_len]
            non_mask_indices[i, :] = context_masks[i][:min_context_len]
    return mask_indices, non_mask_indices

