def loss_pred(pred, target_ema, representations=None, alpha=0.2):
    """Compute MSE loss between predictions and targets.
    
    Args:
        pred: Predictions [nested tensor or regular tensor]
        target_ema: Target embeddings from EMA encoder
        representations: Optional context representations (unused currently)
        alpha: Weight for variance loss (unused currently)
    
    Returns:
        Scalar loss value
    """
    if pred.is_nested:
        # For nested tensors, compute loss per sequence and average
        total_loss = 0.0
        total_elements = 0
        
        for pred_i, target_ema_i in zip(pred, target_ema):
            # pred_i and target_ema_i have shape [seq_len, d_model]
            loss_i = F.mse_loss(pred_i, target_ema_i, reduction='sum')
            total_loss += loss_i
            total_elements += pred_i.numel()
        
        # Average over all elements (not just batch items)
        loss = total_loss / total_elements
    else:
        # For regular tensors, standard MSE
        loss = F.mse_loss(pred, target_ema, reduction='mean')
    
    return loss

def mse_variance_loss(pred, target_ema, representations, alpha = 0.2):
    loss = 0.0
    for pred_i, target_ema_i, representations_i in zip(pred, target_ema, representations):
        loss = loss + F.mse_loss(pred_i, target_ema_i, reduction='mean')
        loss = loss + alpha * F.relu(1.0 - representations_i.std(dim=-1)).mean()
    loss /= len(pred)
    return loss

