class MultimodalSIGReg(nn.Module):
    def __init__(self, knots=17, num_slices=256, prior_type='laplace'):
        super().__init__()
        self.num_slices = num_slices
        
        # Integration parameters
        t = torch.linspace(0, 3, knots, dtype=torch.float32)
        dt = 3 / (knots - 1)
        weights = torch.full((knots,), 2 * dt, dtype=torch.float32)
        weights[[0, -1]] = dt
        
        # Characteristic Function for Prior
        if prior_type == 'laplace':
            phi = 1.0 / (1.0 + t.square())
        else: # Default to Gaussian
            phi = torch.exp(-t.square() / 2.0)
            
        self.register_buffer("t", t)
        self.register_buffer("phi", phi)
        self.register_buffer("weights", weights * phi)

    def forward(self, proj, num_channels):
        """
        proj: (bs * num_channels, n_patches, d) -> Output of PatchTST encoder
        """
        total_batch, n_patches, d = proj.shape
        bs = total_batch // num_channels
        
        # 1. Project to Sliced Space
        A = torch.randn(d, self.num_slices, device=proj.device)
        A = A.div_(A.norm(p=2, dim=0))
        # projs: (bs * num_channels, n_patches, num_slices)
        x_t = (proj @ A).unsqueeze(-1) * self.t.to(proj.device)
        
        # 2. Empirical Characteristic Function
        # x_t: (bs * num_channels, n_patches, num_slices, knots)
        char_cos = x_t.cos().mean(1) # Average over patches
        char_sin = x_t.sin().mean(1)
        
        # --- LOSS A: PRIOR REGULARIZATION ---
        # Ensures every channel-instance follows the Laplacian prior
        err = (char_cos - self.phi.to(proj.device)).square() + char_sin.square()
        loss_prior = (err @ self.weights.to(proj.device)).mean() * n_patches

        # --- LOSS B: CROSS-CHANNEL CONSISTENCY ---
        # Reshape to (bs, num_channels, num_slices, knots)
        char_cos_cc = char_cos.view(bs, num_channels, self.num_slices, -1)
        char_sin_cc = char_sin.view(bs, num_channels, self.num_slices, -1)
        
        # Compare each channel to the mean of all channels for that sample
        mean_cos = char_cos_cc.mean(1, keepdim=True)
        mean_sin = char_sin_cc.mean(1, keepdim=True)
        consist_err = (char_cos_cc - mean_cos).square() + (char_sin_cc - mean_sin).square()
        loss_consistency = (consist_err @ self.weights.to(proj.device)).mean() * n_patches

        return loss_prior, loss_consistency

a = MultimodalSIGReg(prior_type='laplace')
x = torch.randn(6*7, 30, 128) # bs=6, nvars=7
prior_loss, consistency_loss = a(x, num_channels=7)
