class SIGReg(nn.Module):
    def __init__(self, knots=17, num_slices=256):
        super().__init__()
        self.num_slices = num_slices
        t = torch.linspace(0, 3, knots, dtype=torch.float32)
        dt = 3 / (knots - 1)
        weights = torch.full((knots,), 2 * dt, dtype=torch.float32)
        weights[[0, -1]] = dt
        phi = torch.exp(-t.square() / 2.0)
        self.register_buffer("t", t)
        self.register_buffer("phi", phi)
        self.register_buffer("weights", weights * phi)

    def forward(self, proj, padding_mask=None):
        """
        proj: bs * nvars x n_patches x d  -> Output of PatchTST encoder
        padding_mask: bs * nvars x n_patches (1 for valid, 0 for padded)
        """
        A = torch.randn(proj.size(-1), self.num_slices, device=proj.device) # d x num_slices
        A = A.div_(A.norm(p=2, dim=0)) # d x num_slices
        x_t = (proj @ A).unsqueeze(-1) * self.t.to(proj.device) # bs * nvars x n_patches x num_slices x knots
        if padding_mask is not None:
            # Expand mask to match x_t dimensions
           #@ print(padding_mask)
            mask = padding_mask.unsqueeze(-1).unsqueeze(-1) # bs * nvars x n_patches x 1 x 1
            mask = mask.expand_as(x_t)  # bs * nvars x n_patches x num_slices x knots
            # Compute masked mean across batch dimension (dim=-3 = num_patches)
            x_t_masked = x_t * mask
            valid_counts = mask.sum(dim=-3, keepdim=True).clamp(min=1)
            cos_mean = x_t_masked.cos().sum(dim=-3, keepdim=True) / valid_counts
            sin_mean = x_t_masked.sin().sum(dim=-3, keepdim=True) / valid_counts
            
            err = (cos_mean - self.phi.to(proj.device)).square() + sin_mean.square()
            err = err.squeeze(-3)  # Remove the num_patches dimension

            num_samples = mask.size(0) * mask.size(1)
            statistic = (err @ self.weights.to(proj.device)) * (padding_mask.squeeze(-1).sum() / num_samples)
        else:
            err = (x_t.cos().mean(-3) - self.phi.to(proj.device)).square() + x_t.sin().mean(-3).square()
            statistic = (err @ self.weights.to(proj.device)) * proj.size(-2)
        return statistic.mean()

class LeJEPAEncoder(nn.Module):
    def __init__(self, hidden_size=2048, proj_dim=512, **encoder_kwargs):
        super().__init__()
        self.encoder = Encoder(**encoder_kwargs)
        self.proj = VisionMLP(encoder_kwargs['d_model'], [hidden_size, hidden_size, proj_dim], norm_layer=nn.LayerNorm)

    def forward(self, x, mask=None):
        """
        The assumption in LeJEPA is that x has multiple views of shape: bs x n views x n channels x seq_len
        The encoder encodes each view separately and LeJEPA tries to learn invariant representations across views.
        However, for time series data, we can treat each channel as a different view? 
        """
        z = self.encoder(x, mask=mask) # bs * c_in x num_patches x d_model # channels are the views
        proj = self.proj(z) # bs * c_in x num_patches x proj_dim
        return z, proj

class LeJEPALightning(pl.LightningModule):
    def __init__(self,
                 learning_rate,
                 train_size,
                 batch_size,
                 n_gpus,
                 patchtsjepa_encoder_kwargs,
                 num_nodes=1,
                 weight_decay=0.04,
                 use_weight_decay_scheduler=False,
                 final_weight_decay=0.4,
                 epochs=100,
                 optimizer_type='adamw',
                 scheduler_type='OneCycle',
                 scheduler_kwargs={},
                 context_mask_range=(0.2, 0.8), # how many tokens to keep per channel batch?
                 transforms=None, # important for LeJEPA!
                 lambda_reg=0.05,
                 num_slices=256,
                 ):
        super().__init__()
        self.scheduler_type = scheduler_type.lower()
        self.scheduler_kwargs = scheduler_kwargs
        if self.scheduler_type is not None:
            assert self.scheduler_type in ['onecycle', 'cosineannealingwarmrestarts'], "scheduler must be either OneCycle, CosineAnnealingWarmRestarts, or None"
        self.save_hyperparameters()
        self.learning_rate = learning_rate
        self.train_size = train_size
        self.batch_size = batch_size*n_gpus*num_nodes
        self.epochs = epochs
        self.optimizer_type = optimizer_type.lower()
        self.weight_decay = weight_decay
        self.use_weight_decay_scheduler = use_weight_decay_scheduler
        self.final_weight_decay = final_weight_decay
        self.ipe = self.train_size//(self.batch_size)
        self.total_steps = int(self.ipe*self.epochs)
        self.encoder = LeJEPAEncoder(**patchtsjepa_encoder_kwargs)
        self.c_in = patchtsjepa_encoder_kwargs['c_in']
        self.d_model = patchtsjepa_encoder_kwargs['d_model']
        self.num_patch = patchtsjepa_encoder_kwargs['num_patches']
        self.patch_size = patchtsjepa_encoder_kwargs['patch_size']
        self.patch_stride = patchtsjepa_encoder_kwargs['patch_stride']
        self.context_mask_range = context_mask_range
        self.transforms = transforms
        self.lambda_reg = lambda_reg
        self.num_slices = num_slices
    def forward(self, x):
        """
        should output: [bs * nvars x num_patch x d_model] 
        """
        # use context for forward
        x = self.encoder.encoder(x) # bs * c_in x n_patch x d_model
        
        # bs = x.size(0) // self.c_in
        # if x.is_nested:
        #     restored_list = [
        #         torch.stack([
        #             x[i * self.c_in + c] 
        #             for c in range(self.c_in)
        #         ], dim=0).transpose(0, 1)  # Stack channels, then transpose
        #         for i in range(bs)
        #     ]
        #     x = torch.nested.as_nested_tensor(restored_list, layout=torch.jagged)
        #     x = x.transpose(1, 2)  # bs x nvars x num_patch x d_model

        # else:
        #     x = x.unsqueeze(1) # add back channel dim
        # x = x.permute(0,1,3,2) # bs x nvars x d_model x n_patch, 
        return x

    def training_step(self, batch, batch_idx):
        # training_step defines the train loop.
        if self.transforms is not None:
            with torch.no_grad():
                batch = self.transforms(batch)
        x, _ = batch
        bs = x.size(0)

        with torch.no_grad():
            masks = self._create_masks(x)
            masks = masks.to(x.device)
        
        # Encode and Predict the masked tokens
        embs, proj = self.encoder(x, mask=masks)

        # Compute the loss, remember the views are the channels and should be the 0th dimension (bs is 1st)
        sigreg_fn = SIGReg(num_slices=self.num_slices)
        if proj.is_nested:
            seq_lens = [item.size(0) for item in proj.unbind()] # get max n patches
            max_len = max(seq_lens)
            proj = proj.to_padded_tensor(0., output_size=(proj.size(0), max_len, proj.size(2))) # zero pad
            padding_mask = torch.zeros(bs * self.c_in, max_len, device=proj.device, dtype=torch.bool)
            for i, seq_len in enumerate(seq_lens):
                padding_mask[i, :seq_len] = True
            
            # reshape for invariance loss
            padding_mask = padding_mask.reshape(bs, self.c_in, max_len)
            proj = proj.reshape(bs, self.c_in,  max(seq_lens), proj.size(-1)) # bs x nvars x num_patches x proj_dim
            proj = proj.permute(1,0,2,3) # reshape to nvars x bs x num_patches x proj_dim
            proj = proj.reshape(self.c_in, bs * max_len, proj.size(-1)) # nvars x (bs * num_patches) x proj_dim
            padding_mask = padding_mask.permute(1, 0, 2).reshape(self.c_in, bs * max_len, 1) # nvars x bs * num_patches x 1
            sigreg_loss = sigreg_fn(proj, padding_mask=padding_mask)
            valid_proj = proj * padding_mask  # Zero out padded positions
            valid_counts = padding_mask.sum(dim=1, keepdim=True)  # Count valid positions per channel
            proj_mean = valid_proj.sum(dim=1, keepdim=True) / valid_counts.clamp(min=1)  # Avoid div by zero

            diff = (proj_mean - proj).square() * padding_mask  # Only compute diff for valid positions
            inv_loss = diff.sum() / padding_mask.sum()
        else:
            proj = proj.reshape(bs, self.c_in, -1, proj.size(-1)) # bs x nvars x num_patches x proj_dim
            proj = proj.permute(1,0,2,3) # reshape to nvars x bs x num_patches x proj_dim
            proj = proj.reshape(self.c_in, bs * proj.size(2), proj.size(-1)) # nvars x (bs * num_patches) x proj_dim
            sigreg_loss = sigreg_fn(proj, padding_mask=None)
            inv_loss = (proj.mean(0) - proj).square().mean() # invariant loss across views (channels)
        lejepa_loss = sigreg_loss * self.lambda_reg + inv_loss * (1 - self.lambda_reg)
        if lejepa_loss.isnan():
            warnings.warn(f"""
            Train Loss is NaN at batch idx {batch_idx}
            """)
            #lejepa_loss = torch.nan_to_num(lejepa_loss) # convert to 0
            return None

        lejepa_loss = lejepa_loss.to(self.device)
        self.log('train_loss', lejepa_loss, prog_bar=True, on_step=True, on_epoch=True, sync_dist=True)
        return lejepa_loss

    def on_train_batch_start(self, batch, batch_idx):
        # update weight decay
        if self.use_weight_decay_scheduler:
            step = self.global_step
            T_max = int(self.ipe * self.epochs)
            progress = step / T_max
            new_wd = self.final_weight_decay + (self.weight_decay - self.final_weight_decay) * 0.5 * (1. + math.cos(math.pi * progress))

            if self.final_weight_decay <= self.weight_decay:
                new_wd = max(self.final_weight_decay, new_wd)
            else:
                new_wd = min(self.final_weight_decay, new_wd)

            for group in self.optimizer.param_groups:
                if ('WD_exclude' not in group) or not group['WD_exclude']:
                    group['weight_decay'] = new_wd
    
    def validation_step(self, batch, batch_idx):
        x, _ = batch
        
        # Encode and Predict the masked tokens

        with torch.no_grad():
            masks = self._create_masks(x)
            masks = masks.to(x.device)
        
        # Encode and Predict the masked tokens
        embs, proj = self.encoder(x, mask=masks)
        bs = x.size(0)

        sigreg_fn = SIGReg(num_slices=self.num_slices)
        if proj.is_nested:
            seq_lens = [item.size(0) for item in proj.unbind()] # get max n patches
            max_len = max(seq_lens)
            proj = proj.to_padded_tensor(0., output_size=(proj.size(0), max_len, proj.size(2))) # zero pad
            padding_mask = torch.zeros(bs * self.c_in, max_len, device=proj.device, dtype=torch.bool)
            for i, seq_len in enumerate(seq_lens):
                padding_mask[i, :seq_len] = True
            
            # reshape for invariance loss
            padding_mask = padding_mask.reshape(bs, self.c_in, max_len)
            proj = proj.reshape(bs, self.c_in,  max(seq_lens), proj.size(-1)) # bs x nvars x num_patches x proj_dim
            proj = proj.permute(1,0,2,3) # reshape to nvars x bs x num_patches x proj_dim
            proj = proj.reshape(self.c_in, bs * max_len, proj.size(-1)) # nvars x (bs * num_patches) x proj_dim
            padding_mask = padding_mask.permute(1, 0, 2).reshape(self.c_in, bs * max_len, 1) # nvars x bs * num_patches x 1
            sigreg_loss = sigreg_fn(proj, padding_mask=padding_mask)
            valid_proj = proj * padding_mask  # Zero out padded positions
            valid_counts = padding_mask.sum(dim=1, keepdim=True)  # Count valid positions per channel
            proj_mean = valid_proj.sum(dim=1, keepdim=True) / valid_counts.clamp(min=1)  # Avoid div by zero

            diff = (proj_mean - proj).square() * padding_mask  # Only compute diff for valid positions
            inv_loss = diff.sum() / padding_mask.sum()
        else:
            proj = proj.reshape(bs, self.c_in, -1, proj.size(-1)) # bs x nvars x num_patches x proj_dim
            proj = proj.permute(1,0,2,3) # reshape to nvars x bs x num_patches x proj_dim
            proj = proj.reshape(self.c_in, bs * proj.size(2), proj.size(-1)) # nvars x (bs * num_patches) x proj_dim
            sigreg_loss = sigreg_fn(proj, padding_mask=None)
            inv_loss = (proj.mean(0) - proj).square().mean() # invariant loss across views (channels)
        lejepa_loss = sigreg_loss * self.lambda_reg + inv_loss * (1 - self.lambda_reg)

        if lejepa_loss.isnan():
            warnings.warn(f"""
            Train Loss is NaN at batch idx {batch_idx}
            """)
            lejepa_loss = torch.nan_to_num(lejepa_loss) # convert to 0

        lejepa_loss = lejepa_loss.to(self.device)

        self.log("val_loss", lejepa_loss, prog_bar=True, on_step=True, on_epoch=True, sync_dist=True)

    def configure_optimizers(self):
        param_groups = [ # exclude bias and layer norm parameters from weight decay
            {
                'params': (p for n, p in self.encoder.named_parameters()
                        if ('bias' not in n) and (len(p.shape) != 1))
            },  {
                'params': (p for n, p in self.encoder.named_parameters()
                        if ('bias' in n) or (len(p.shape) == 1)),
                'WD_exclude': True,
                'weight_decay': 0,
            }, 
        ]
        self.optimizer = torch.optim.AdamW(param_groups, lr=self.learning_rate, weight_decay=self.weight_decay if not self.use_weight_decay_scheduler else 0.0, fused=False) if self.optimizer_type == 'adamw' else\
                     torch.optim.Adam(param_groups, lr=self.learning_rate, weight_decay=self.weight_decay if not self.use_weight_decay_scheduler else 0.0, fused=False)
        if self.scheduler_type == 'onecycle':
            scheduler = OneCycleLR(self.optimizer, total_steps=self.trainer.estimated_stepping_batches, **self.scheduler_kwargs)
            lr_scheduler = {'scheduler': scheduler, 'interval': 'step'}
            return {'optimizer': self.optimizer, 'lr_scheduler': lr_scheduler}
        elif self.scheduler_type == 'cosineannealingwarmrestarts':
            scheduler = CosineAnnealingWarmRestarts(self.optimizer, **self.scheduler_kwargs) # T_0=self.epochs//10, T_mult=2, eta_min=1e-8) # lr max is initial LR
            lr_scheduler = {'scheduler': scheduler, 'interval': 'epoch'}
            return {'optimizer': self.optimizer, 'lr_scheduler': lr_scheduler}
        else:
            return self.optimizer
    
    def _create_masks(self, x):
        # Create the mask for the patches
        batch_size = x.size(0)
        #channel_size = x.size(1)
        sample_n_patches = []
        for x_i in x:
            num_patches = int((max(x_i.size(-1), self.patch_size)-self.patch_stride) // self.patch_stride + 1)
            if ((x_i.size(-1)-self.patch_size) % self.patch_stride != 0):
                num_patches += 1
            sample_n_patches.append(num_patches)
        
        mask_indices_t = []
        
        # Create ONE mask per sample, apply to ALL channels
        for i, n_patch in enumerate(sample_n_patches):
            mask_ratio = self.context_mask_range[0] + torch.rand(1).item() * (self.context_mask_range[1] - self.context_mask_range[0])
            perm = torch.randperm(n_patch)
            num_masks = int(n_patch * mask_ratio)
            
            mask_indices = perm[:num_masks].sort().values
            
            # Replicate same mask for all channels
            for c in range(self.c_in):
                mask_indices_t.append(mask_indices)
        # for x_i in x:
        #     num_patches = int((max(x_i.size(-1), self.patch_size)-self.patch_stride) // self.patch_stride + 1)
        #     if ((x_i.size(-1)-self.patch_size) % self.patch_stride != 0):
        #         num_patches += 1
        #     added_batches = channel_size
        #     batch_size += added_batches
        #     sample_n_patches.extend(num_patches for i in range(added_batches))
        
        # mask_indices_t = []
        # return_nested = x.is_nested
        # for i, n_patch in enumerate(sample_n_patches):
        #     mask_ratio = self.context_mask_range[0] + torch.rand(1).item() * (self.context_mask_range[1] - self.context_mask_range[0])
        #     perm = torch.randperm(n_patch)
        #     num_masks = int(n_patch * mask_ratio)
                        
        #     mask_indices = perm[:num_masks]

        #     assert len(mask_indices) > 0, "No context indices created"
        #     mask_indices_t.append(mask_indices.sort().values)
        return_nested = x.is_nested
        if return_nested:
            mask_indices = torch.nested.as_nested_tensor(mask_indices_t, layout=torch.jagged)
        else:
            min_context_len = min(len(mask) for mask in mask_indices_t)
            mask_indices = torch.zeros((batch_size, min_context_len), dtype=torch.long)

            for i in range(batch_size):
                mask_indices[i, :] = mask_indices_t[i][:min_context_len]
        return mask_indices
        

